const first = $input.first();
const input = first && first.json ? first.json : {};
const body = (input.body && typeof input.body === 'object') ? input.body : input;
const testId = String(body.test_id || '').trim();
const caption = String(body.caption || body.carousel?.caption || '').trim();
const mediaRaw = Array.isArray(body.carousel?.media) ? body.carousel.media : [];
const media = mediaRaw.map((m, idx) => ({ position: Number(m?.position || (idx + 1)), image_url: String(m?.image_url || '').trim() })).filter((m) => m.position > 0 && m.image_url);
media.sort((a, b) => a.position - b.position);
if (!testId) throw new Error('Missing test_id');
if (!caption) throw new Error('Missing carousel caption');
if (media.length < 2 || media.length > 10) throw new Error(`Invalid carousel media count: ${media.length}`);
const dryRun = body.dry_run === true || String(body.dry_run || '').toLowerCase() === 'true';
const testMode = body.test_mode === true || String(body.test_mode || '').toLowerCase() === 'true';
const diagnostic = body.diagnostic === true || String(body.diagnostic || '').toLowerCase() === 'true';
return [{ json: { ...body, test_id: testId, caption, carousel: { ...(body.carousel || {}), media }, dry_run: dryRun, test_mode: testMode, diagnostic } }];

const first = $input.first();
const j = first && first.json ? first.json : {};
const media = Array.isArray(j.carousel?.media) ? j.carousel.media : [];
if (media.length < 2 || media.length > 10) throw new Error(`Carousel media count must be 2..10, got ${media.length}`);
for (const m of media) {
  const u = String(m.image_url || '').trim();
  if (!/^https?:\/\//i.test(u)) throw new Error(`Invalid image_url: ${u}`);
}
return [{ json: { ...j, image_count: media.length, child_expected_count: media.length } }];

const first = $input.first();
const j = first && first.json ? first.json : {};
const media = Array.isArray(j.carousel?.media) ? j.carousel.media : [];
return media.map((m, idx) => ({
  json: {
    ...j,
    child_order: idx + 1,
    child_expected_count: media.length,
    image_url: String(m.image_url || '').trim(),
  }
}));

const raw = $input.all();
const all = raw.map((i, idx) => ({ idx, json: i.json || {} }));
if (!all.length) throw new Error('No child container responses');

const first = all[0].json || {};
const expectedFromField = Number(first.child_expected_count || 0);
const expectedFromInputCount = all.length;
const expected = expectedFromField > 0 ? expectedFromField : expectedFromInputCount;

const ordered = all
  .slice()
  .sort((a, b) => Number(a.json.child_order || (a.idx + 1)) - Number(b.json.child_order || (b.idx + 1)));

const childIds = ordered
  .map((r) => String((r.json || {}).id || '').trim())
  .filter(Boolean);

if (!expected || childIds.length !== expected || expectedFromInputCount !== expected) {
  throw new Error(`CHILD_COUNT_MISMATCH expected=${expected} actual=${childIds.length}`);
}

return [{ json: { ...first, child_expected_count: expected, carousel_child_ids: childIds } }];

const j = $json || {};
const mediaId = String(j.id || '').trim();
if (!mediaId) throw new Error('Carousel publish did not return media id');
return { json: { ...j, publish_success: true, publish_status: 'success', media_id: mediaId, route_action: 'approve_carousel' } };

const first = $input.first();
const j = first && first.json ? first.json : {};
const isDryRun = j.test_mode === true || j.dry_run === true || j.diagnostic === true;
const store = $getWorkflowStaticData('global');
const nowMs = Date.now();
const nowIso = new Date(nowMs).toISOString();
const throttleMs = 60 * 60 * 1000;
const throttleMinutes = 60;

function toMs(value) {
  if (!value) return 0;
  const t = new Date(String(value)).getTime();
  return Number.isFinite(t) ? t : 0;
}

function recentEntry(entry) {
  const t = toMs(entry?.attempted_at || entry?.published_at || entry?.triggered_at || entry?.created_at || entry?.at || entry);
  return t > 0 && (nowMs - t) < throttleMs;
}

store.carousel_publish_attempt_log = Array.isArray(store.carousel_publish_attempt_log) ? store.carousel_publish_attempt_log : [];
store.daily_publish_success_log = Array.isArray(store.daily_publish_success_log) ? store.daily_publish_success_log : [];

if (isDryRun) {
  store.last_carousel_publish_gate = {
    status: 'dry_run',
    test_id: String(j.test_id || ''),
    checked_at: nowIso,
    publish_triggered: false,
  };
  return [{ json: { status: 'dry_run', test_id: String(j.test_id || ''), publish_triggered: false } }];
}

const recentAttempt = store.carousel_publish_attempt_log.find(recentEntry);
const recentSuccess = store.daily_publish_success_log.find(recentEntry);
const recentLegacy = [
  store.last_carousel_publish_attempt_at,
  store.last_carousel_publish_at,
  store.last_publish_attempt_at,
  store.last_publish_success_at,
].find((value) => recentEntry(value));
const recent = recentAttempt || recentSuccess || recentLegacy;

if (recent) {
  store.last_carousel_publish_gate = {
    status: 'throttled',
    test_id: String(j.test_id || ''),
    checked_at: nowIso,
    throttle_window_minutes: throttleMinutes,
    recent_publish_at: String(recent?.attempted_at || recent?.published_at || recent?.triggered_at || recent?.created_at || recent?.at || recentLegacy || ''),
    publish_triggered: false,
  };
  return [{
    json: {
      status: 'throttled',
      route_action: String(j.route_action || 'approve_carousel'),
      test_id: String(j.test_id || ''),
      throttle_window_minutes: throttleMinutes,
      publish_triggered: false,
    }
  }];
}

const attempt = {
  test_id: String(j.test_id || ''),
  route_action: String(j.route_action || 'approve_carousel'),
  attempted_at: nowIso,
  status: 'attempt_started',
};
store.carousel_publish_attempt_log.push(attempt);
store.carousel_publish_attempt_log = store.carousel_publish_attempt_log.slice(-100);
store.last_carousel_publish_attempt_at = nowIso;
store.last_carousel_publish_gate = {
  status: 'allowed',
  test_id: attempt.test_id,
  checked_at: nowIso,
  throttle_window_minutes: throttleMinutes,
  publish_triggered: true,
};

return [{ json: { ...j, publish_throttle_checked: true, publish_attempt_logged_at: nowIso, throttle_window_minutes: throttleMinutes } }];

